local function C_4()
local script = G2L["4"];
	local button = script.Parent
	local player = game.Players.LocalPlayer
	local character = player.Character or player.CharacterAdded:Wait()
	local humanoidRootPart = character:WaitForChild("HumanoidRootPart")
	local lockersFolder = game.Workspace:WaitForChild("Item Spawns"):WaitForChild("lockers")
	local running = false

	local function freezeCharacter()
		for _, v in pairs(character:GetChildren()) do
			if v:IsA("BasePart") then
				v.Anchored = true
			end
		end
	end

	local function unfreezeCharacter()
		for _, v in pairs(character:GetChildren()) do
			if v:IsA("BasePart") then
				v.Anchored = false
			end
		end
	end

	local function fireProximityPrompt(prompt)
		if prompt and prompt:IsA("ProximityPrompt") then
			local promptService = game:GetService("ProximityPromptService")
			promptService.PromptButtonHoldBegan:Fire(prompt, player)
			promptService.PromptButtonHoldEnded:Fire(prompt, player)
		end
	end

	local function teleportAndTriggerLockers()
		running = not running
		if running then
			freezeCharacter()
			while running do
				for _, locker in pairs(lockersFolder:GetChildren()) do
					if not running then break end
					if locker:IsA("Model") then
						local unionOp = locker:FindFirstChildOfClass("UnionOperation")
						if unionOp then
							local prompt = unionOp:FindFirstChild("prompt")
							if prompt and prompt:IsA("ProximityPrompt") then
								humanoidRootPart.CFrame = unionOp.CFrame + Vector3.new(0, 3, 0) -- Teleport above locker
								prompt.HoldDuration = 0
								task.wait(0.1) -- Small delay to ensure player registers as near
								fireProximityPrompt(prompt)
								task.wait(3) -- Stay at the locker
							end
						end
					end
				end
				task.wait(3) -- Small pause before looping again
			end
			unfreezeCharacter()
		end
	end

	button.MouseButton1Click:Connect(teleportAndTriggerLockers)

end;
task.spawn(C_4);
